#include <stdio.h>

void dec_to_bin(int n){
    if (n == 0) return;
    else{
        dec_to_bin(n / 2);
        printf("%d", n % 2);
    }
}

int main(){
    int decimal;

    printf("십진수 입력:");
    scanf("%d", &decimal);

    dec_to_bin(decimal);

    return 0;
}

#include <stdio.h>

int main(void) {
    int two[10];
    two[0] = 1;
    for (int i = 1; i < 10; ++i) two[i] = 2 * two[i - 1];
    for (int i = 0; i < 10; ++i)
        printf("%d%s", two[i], i == 9 ? "\n" : " ");
    return 0;
}

